def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Update reputation based on observed action with a simple linear step
    if observation["action"] == "donate":
        new_rep = min(1.0, current_reputation + 0.2)
    else:
        new_rep = max(-1.0, current_reputation - 0.2)
    return float(new_rep)

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Only donate if the recipient has a good reputation (indirect reciprocity)
    # Use a low threshold to be somewhat generous
    THRESHOLD = 0.1
    return recipient_reputation > THRESHOLD
